# Si el nombre de la categoría contiene alguna de estas palabras, es de calzado.
PALABRAS_CALZADO = [
    "zapat", "tenis", "calzado", "bota", "botin", "sandalia",
    "huarache", "chancla", "mocasin", "tacon", "sneaker",
]


def normalizar(texto):
    t = unicodedata.normalize("NFKD", (texto or "").strip().lower())
    return "".join(c for c in t if not unicodedata.combining(c))


def marcar_calzado(apps, schema_editor):
    """Las categorías de zapatos quedan como calzado; las demás siguen como ropa.
    No cambia ninguna prenda: si una tiene una talla que ya no aplica (por ejemplo
    un zapato con talla "L"), se corrige editándola desde la app."""
    Categoria = apps.get_model("quickstart", "Categoria")
    for c in Categoria.objects.all():
        nombre = normalizar(c.nombre)
        if any(p in nombre for p in PALABRAS_CALZADO):
            c.tipo_talla = "calzado"
            c.save(update_fields=["tipo_talla"])


